async function expectFailure(f,{pattern,timing}={}){const s=storage();try{await assert.rejects(captureVisibleCanvas(f.page,s.path,timing?{timing}:{}),pattern);noOutput(s);return f;}finally{s.cleanup();}}

const current040CaptureBody="export async function capturePublicCDPCanvas(page,{canvasClip,timing={now:()=>performance.now(),set:setTimeout,clear:clearTimeout}}){\n  assert.equal(typeof canvasClip,'function','pinned baseline canvasClip required');const started=timing.now(),deadline=started+CAPTURE_MS,timeoutError=new Error('Public CDP capture deadline10000ms exceeded');let expired=false,closed=false,session,handle,rawHandle,failed=false,primary,result;\n  const cleanupTasks=new Map();\n  const cleanup=(object,method)=>{if(!object)return Promise.resolve();if(!cleanupTasks.has(object)){const task=Promise.resolve().then(()=>object[method]());task.catch(()=>{});cleanupTasks.set(object,task);}return cleanupTasks.get(object);};\n  let rejectDeadline;const timeout=new Promise((_,reject)=>{rejectDeadline=reject;});timeout.catch(()=>{});const timer=timing.set(()=>{expired=true;rejectDeadline(timeoutError);},CAPTURE_MS);\n  const guard=()=>{if(expired||timing.now()>=deadline){expired=true;throw timeoutError;}};\n  const within=async promise=>{guard();const value=await Promise.race([Promise.resolve(promise),timeout]);guard();return value;};\n  const owned=async(promise,method)=>{const pending=Promise.resolve(promise);pending.then(object=>{if(expired||closed||timing.now()>=deadline)cleanup(object,method);},()=>{});return within(pending);};\n  try{\n    rawHandle=await owned(page.evaluateHandle(() => {\n      const matches=document.querySelectorAll('.cc-pixi-stage canvas');\n      if(matches.length!==1)throw new Error('Exactly one current document canvas required');\n      const node=matches[0];\n      if(!(node instanceof HTMLCanvasElement)||node.ownerDocument!==document||!node.isConnected)throw new Error('Current document connected HTMLCanvasElement required');\n      return Object.defineProperty(Object.create(null),'node',{value:node,enumerable:true,writable:false,configurable:false});\n    }),'dispose');assert.ok(rawHandle,'attached raw canvas handle required');handle=rawHandle;guard();const before=await within(handle.evaluate(readOwnedCanvas)),clip=canvasClip(before);\n    session=await owned(page.context().newCDPSession(page),'detach');const response=await within(session.send('Page.captureScreenshot',{format:'png',clip:{...clip,scale:1},fromSurface:true,captureBeyondViewport:false,optimizeForSpeed:false}));\n    const png=strictBase64(response?.data),decoded=decodeStrictPng(png,clip);guard();const after=await within(handle.evaluate(readOwnedCanvas));canvasClip(after);assert.deepEqual(after,before,'canvas identity/current connection/geometry changed');\n    result={png,receipt:{method:'public-cdp-page-captureScreenshot-canvas-viewport-clip-v1',clip,before,after,bytes:png.length,sha256:sha256(png),pixelSHA256:decoded.pixelSHA256,qualification:'Diagnostic public CDP comparison only; both APIs may share Chromium backend; no canonical receipt enum or causal claim'}};\n  }catch(error){failed=true;primary=error;}\n  // Start both disposals even if one fails or the capture deadline has elapsed.\n  const disposal=[cleanup(session,'detach'),cleanup(rawHandle,'dispose')];\n  try{const outcomes=await within(Promise.allSettled(disposal));for(const outcome of outcomes)if(outcome.status==='rejected'&&!failed){failed=true;primary=outcome.reason;}}catch(error){if(!failed){failed=true;primary=error;}}\n  closed=true;timing.clear(timer);if(failed)throw primary;guard();result.receipt.elapsedMs=timing.now()-started;result.receipt.deadlineHostMs=deadline;\n  // No publisher or file API: late/failed results cannot escape this helper.\n  return result;\n}\n";
const expectedInventory={"await": 15, "then": 3, "catch": 3, "finally": 1, "race": 1, "allSettled": 2, "timer": 1, "clear": 1, "session": 1, "sendSites": 2};

function restoreCurrent040(source){const a=source.indexOf('// Public Runtime transport owns a private envelope;'),b=source.indexOf('\nexport function canvasClip(',a);assert.ok(a>=0&&b>a);return source.slice(0,a)+current040CaptureBody+source.slice(b);}
function assertWholeContract(source){
 const patterns={await:/\bawait\b/g,then:/\.then\(/g,catch:/\.catch\(/g,finally:/\.finally\(/g,race:/Promise\.race\(/g,allSettled:/Promise\.allSettled\(/g,timer:/timing\.set\(/g,clear:/timing\.clear\(/g,session:/page\.context\(\)\.newCDPSession\(/g,sendSites:/session\.send\(/g};
 for(const [key,regex]of Object.entries(patterns))assert.equal((source.match(regex)??[]).length,expectedInventory[key],key);
 assert.doesNotMatch(source,/page\.evaluateHandle\(|handle\.evaluate\(|getPropert(?:y|ies)\(|jsonValue\(|\.locator\(|_channel|_delegate|_objectId|releaseObjectGroup|JSON\.stringify|JSON\.parse/);
 for(const token of ["uniqueContextId:selected.unique","functionDeclaration:taggedOwnedCanvas.toString()","const envelope=this;","descriptor.writable!==false","descriptor.configurable!==false","Object.is(value,-0)?['z']","while(pending.size)await Promise.allSettled([...pending]);","for(const objectId of objectIds)","const disposal=cleanup();"])assert.ok(source.includes(token),token);
 assert.equal((source.match(/invoke\('Runtime.callFunctionOn'/g)??[]).length,2);assert.equal((source.match(/invoke\('Runtime.evaluate'/g)??[]).length,1);
 const restored=restoreCurrent040(source);assert.equal(Buffer.byteLength(restored),13890);assert.equal(sha256(restored),'2ee10b527ab7ba22ae1cf0baef584eab19612d8b84eca1c850615f2be2ed86ee');
 assert.equal(source.slice(source.indexOf('export async function captureVisibleCanvas')),restored.slice(restored.indexOf('export async function captureVisibleCanvas')),'publication exact');
 const numericBody=restored.match(/export function readCanvas\(node\)\{([\s\S]*?)\n\}/)[1];assert.ok(source.includes(numericBody.trim().replace('return {','const state={')),'complete14-field state body');
}

test('canonical integrated helper publishes current validated PNG and exact strict receipt after owned closure',async()=>{const s=storage(),f=fixture();try{const receipt=await captureVisibleCanvas(f.page,s.path);assert.deepEqual(Object.keys(receipt).sort(),['method','clip','before','after','bytes','sha256','qualification'].sort());assert.equal(receipt.method,PUBLIC_CDP_CAPTURE_METHOD);assert.equal(receipt.sha256,sha256(fs.readFileSync(s.path)));assert.deepEqual(fs.readdirSync(s.root),['zk682-resource-growth-final.png']);assert.deepEqual(f.stats().sent,{method:'Page.captureScreenshot',args:{format:'png',clip:{x:0,y:0,width:2,height:1,scale:1},fromSurface:true,captureBeyondViewport:false,optimizeForSpeed:false}});assert.deepEqual([f.stats().detach,f.stats().dispose],[1,1]);decodeStrictPng(fs.readFileSync(s.path),receipt.clip);}finally{s.cleanup();}});
test('canonical integrated helper preserves every falsy primary despite secondary cleanup and publishes nothing',async()=>{for(const primary of [undefined,null,false,0,'']){const s=storage(),f=fixture({primary,detachError:new Error('detach secondary'),disposeError:new Error('dispose secondary')});try{let rejected=false,actual;try{await captureVisibleCanvas(f.page,s.path);}catch(error){rejected=true;actual=error;}assert.equal(rejected,true);assert.equal(actual,primary);assert.deepEqual(fs.readdirSync(s.root),[]);assert.deepEqual([f.stats().detach,f.stats().dispose],[1,1]);}finally{s.cleanup();}}});
test('canonical integrated helper discards late capture result with no filesystem publication',async()=>{const s=storage(),c=clock(),pending=deferred(),f=fixture({sendPromise:pending.promise});try{const result=captureVisibleCanvas(f.page,s.path,{timing:c.timing});await tick();c.expire();await assert.rejects(result,/deadline10000ms/);pending.resolve({data:png().toString('base64')});await tick();assert.deepEqual(fs.readdirSync(s.root),[]);assert.deepEqual([f.stats().detach,f.stats().dispose],[1,1]);}finally{s.cleanup();}});
test('canonical integrated delayed monotonic acquisition owns handle and session before deadline assignment',async()=>{for(const hold of ['A','session']){const s=storage(),c=clock(),f=vmFixture({hold});try{const result=captureVisibleCanvas(f.page,s.path,{timing:c.timing});await tick();c.elapse();f.release();await assert.rejects(result,/deadline10000ms/);await tick();assert.equal(f.stats().disposed,hold==='A'?1:0);assert.equal(f.stats().detached,1);noOutput(s);}finally{s.cleanup();}}});
test('canonical integrated cleanup failure and pending detach deadline never publish final PNG',async()=>{for(const field of ['detachError','disposeError']){const s=storage(),primary=Symbol(field),f=fixture({[field]:primary});try{await assert.rejects(captureVisibleCanvas(f.page,s.path),error=>error===primary);assert.deepEqual([f.stats().detach,f.stats().dispose],[1,1]);assert.deepEqual(fs.readdirSync(s.root),[]);}finally{s.cleanup();}}const s=storage(),c=clock(),pending=deferred(),f=fixture({detachPromise:pending.promise});try{const result=captureVisibleCanvas(f.page,s.path,{timing:c.timing});await tick();c.expire();await assert.rejects(result,/deadline10000ms/);pending.resolve();await tick();assert.deepEqual(fs.readdirSync(s.root),[]);}finally{s.cleanup();}});
test('canonical publication refuses pre-existing file and symlink without deleting either',async()=>{for(const symlink of [false,true]){const s=storage(),sentinel=join(s.root,'sentinel');try{fs.writeFileSync(sentinel,'keep');if(symlink)fs.symlinkSync(sentinel,s.path);else fs.writeFileSync(s.path,'existing');await assert.rejects(captureVisibleCanvas(fixture().page,s.path),error=>error.code==='EEXIST');assert.equal(fs.readFileSync(s.path,'utf8'),symlink?'keep':'existing');assert.equal(fs.readFileSync(sentinel,'utf8'),'keep');assert.equal(fs.lstatSync(s.path).isSymbolicLink(),symlink);assert.ok(!fs.readdirSync(s.root).some(name=>name.includes('.cdp-pending-')));}finally{s.cleanup();}}});
test('canonical publication checks total deadline before promotion and rolls back late exclusive link',async()=>{for(const phase of ['write','link']){const s=storage(),c=clock();let links=0;const io={...fs,writeFileSync:(...args)=>{fs.writeFileSync(...args);if(phase==='write')c.elapse();},linkSync:(...args)=>{links++;fs.linkSync(...args);if(phase==='link')c.elapse();}};try{await assert.rejects(captureVisibleCanvas(fixture().page,s.path,{timing:c.timing,io}),/total capture\/publication deadline10000ms/);assert.equal(links,phase==='link'?1:0);assert.deepEqual(fs.readdirSync(s.root),[]);}finally{s.cleanup();}}});
test('canonical publication preserves falsy filesystem primary despite failed rollback cleanup',async()=>{for(const primary of [undefined,null,false,0,'']){const s=storage(),io={...fs,linkSync:()=>{throw primary;},unlinkSync:()=>{throw new Error('secondary rollback');}};try{let rejected=false,actual;try{await captureVisibleCanvas(fixture().page,s.path,{io});}catch(error){rejected=true;actual=error;}assert.equal(rejected,true);assert.equal(actual,primary);assert.equal(fs.existsSync(s.path),false);}finally{s.cleanup();}}});
