test('canonical strict base64 PNG decode and geometry reject malformed oversize blank stale duplicate inputs',async()=>{assert.throws(()=>strictBase64('A'.repeat(4*Math.ceil(1048576/3)+4)));for(const data of ['',png().toString('base64')+'\n','!!!!'])assert.throws(()=>strictBase64(data));for(const bytes of [png({blank:true}),png({transparent:true}),Buffer.alloc(0),Buffer.alloc(1048577)])assert.throws(()=>decodeStrictPng(bytes));const crc=Buffer.from(png());crc[crc.length-1]^=1;assert.throws(()=>decodeStrictPng(crc));for(const options of [{count:0},{count:2},{data:'!!!!'},{after:{...state,current:false}},{after:{...state,connected:false}},{after:{...state,visible:false}},{after:{...state,width:0}},{after:{...state,dpr:2}},{after:{...state,x:0.5}}]){const s=storage();try{await assert.rejects(captureVisibleCanvas(fixture(options).page,s.path));assert.deepEqual(fs.readdirSync(s.root),[]);}finally{s.cleanup();}}assert.deepEqual(canvasClip(state),{x:0,y:0,width:2,height:1});});
