  for(const phase of ['B','D']){
    for(const subtype of [undefined,null,'node','object',false,0,'',{},[]]){const fixture=vmFixture({transformReply:(at,response)=>{if(at===phase)response.result.subtype=subtype;return response;}});await expectFailure(fixture);assert.equal(fixture.stats().disposed,1);assert.equal(fixture.stats().detached,1);}
    let getters=0;const accessor=vmFixture({transformReply:(at,response)=>{if(at===phase)Object.defineProperty(response.result,'subtype',{get:()=>{getters++;return 'array';}});return response;}});await expectFailure(accessor,{pattern:/accessor refused: subtype/});assert.equal(getters,0);assert.equal(accessor.stats().disposed,1);
    const invalid=[response=>{response.result.value={};},response=>{response.result.value=null;},response=>{response.result.value='not-array';},response=>{response.result.value.pop();},response=>{delete response.result.value[5];},response=>{response.result.value[0]='unknown-version';},response=>{response.result.value[1]=['b',1];},response=>{response.result.value[5]=['unknown'];},response=>{response.result.value[5]=['n',-0];},response=>{response.result.value[5]=['n',NaN];},response=>{response.result.value[5]=['z',0];},response=>{response.result.value.extra=1;},response=>{response.result.type='string';},response=>{response.result.objectId='unexpected-owned-state';},response=>{response.result.unserializableValue='-0';}];
    for(const mutate of invalid){const fixture=vmFixture({transformReply:(at,response)=>{if(at===phase){delete response.result.subtype;mutate(response);}return response;}});await expectFailure(fixture);assert.equal(fixture.stats().disposed,1);assert.equal(fixture.stats().detached,1);}
  }
